<!doctype html><html><head><meta charset="utf-8"><title>Party Statement</title><style>@page{size:A4 landscape;margin:6mm 7mm}*{box-sizing:border-box}body{font:10px Arial;color:#182536;margin:0}.head{display:flex;justify-content:space-between;border-bottom:1px solid #aebdce;padding-bottom:7px}.company{display:flex;gap:8px;align-items:center}.company img{width:38px;height:38px;object-fit:contain}.company strong,.company small{display:block}.title{text-align:right}.title h1{font-size:16px;margin:0}.title p{margin:3px 0;color:#536b84}.party{display:flex;gap:16px;padding:7px 0}.party span{color:#536b84}table{width:100%;border-collapse:collapse;table-layout:auto}th,td{padding:4px 5px;border-bottom:1px solid #ccd5df;text-align:left;vertical-align:top}th{background:#edf3f9;font-size:9px}th:nth-last-child(-n+3),td:nth-last-child(-n+3){text-align:right;white-space:nowrap}td:nth-child(1),td:nth-child(2),td:nth-child(3),td:nth-child(4),td:nth-child(5),td:nth-child(6),td:nth-child(7){white-space:nowrap}td:nth-child(8){min-width:130px}footer{margin-top:10px;text-align:right;font-size:10px}</style></head><body><div class="head"><div class="company">@if(!empty($companyProfile['logo']))<img src="{{ $companyProfile['logo'] }}" alt="Company logo">@endif<div><strong>{{ $companyProfile['name'] ?? '' }}</strong><small>{{ $companyProfile['subtitle'] ?? '' }}</small><small>{{ implode(' · ', array_filter([$companyProfile['address'] ?? '',$companyProfile['phone'] ?? '',$companyProfile['email'] ?? '',$companyProfile['website'] ?? ''])) }}</small></div></div><div class="title"><h1>{{ $statement['filters']['type']==='vendor' ? 'VENDOR ACCOUNT STATEMENT' : 'CUSTOMER ACCOUNT STATEMENT' }}</h1><p>Generated {{ now()->format('d M Y H:i') }} · Currency: PKR</p><p>{{ $statement['filters']['from'] }} to {{ $statement['filters']['to'] }}</p></div></div><div class="party"><strong>{{ $party['name'] ?? '—' }}</strong><span>{{ $statement['filters']['type']==='vendor' ? 'Vendor' : 'Customer' }}{{ !empty($party['code']) ? ' · '.$party['code'] : '' }}</span></div><table><thead><tr><th>Date</th><th>Type</th><th>Invoice / Ref.</th><th>Booking No.</th><th>Product</th><th>Passenger / Group</th><th>Service Ref.</th><th>Sector / Description</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody>@foreach($statement['rows'] as $row)<tr><td>{{ $row['date'] }}</td><td>{{ $row['type'] }}</td><td>{{ $row['reference'] ?: '—' }}</td><td>{{ $row['booking_no'] }}</td><td>{{ $row['product'] }}</td><td>{{ $row['party'] }}</td><td>{{ $row['service_ref'] }}</td><td>{{ $row['description'] }}</td><td>{{ number_format($row['debit'],2) }}</td><td>{{ number_format($row['credit'],2) }}</td><td>{{ number_format(abs($row['balance']),2) }} {{ $row['balance'] < 0 ? 'Cr' : 'Dr' }}</td></tr>@endforeach</tbody></table><footer>Opening {{ number_format(abs($statement['opening']),2) }} · Debit {{ number_format($statement['total_debit'],2) }} · Credit {{ number_format($statement['total_credit'],2) }} · Closing {{ number_format(abs($statement['closing']),2) }} {{ $statement['closing_side'] }}<br>{{ $statement['caption'] }}</footer></body></html>
